INSERT INTO people (id, canonical_name, first_name, last_name, country, occupation, industry, description, is_billionaire, giving_pledge) VALUES
('b0000000-0000-0000-0000-000000000026', 'Phil Knight', 'Philip', 'Knight', 'United States', 'Co-Founder & Chairman Emeritus, Nike, Inc.', 'Apparel & Retail', 'Co-founder of Nike. Major individual donor to higher education and scientific research, notably the University of Oregon and Oregon Health & Science University (OHSU).', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000027', 'Dustin Moskovitz & Cari Tuna', 'Dustin', 'Moskovitz', 'United States', 'Co-Founder & CEO, Asana / Co-Founder, Good Ventures', 'Technology & Philanthropy', 'Facebook co-founder and Asana CEO. With Cari Tuna, established Good Ventures and Open Philanthropy, dedicating fortune to effective altruism, global health, and biosecurity.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000028', 'Jensen Huang & Lori Huang', 'Jen-Hsun', 'Huang', 'United States', 'Founder, President & CEO, Nvidia', 'Semiconductors & AI', 'Founder and CEO of Nvidia. Has contributed significant personal direct funding to university engineering and collaborative innovation complexes.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000029', 'Marc Benioff & Lynne Benioff', 'Marc', 'Benioff', 'United States', 'Chair & CEO, Salesforce', 'Enterprise Cloud & Software', 'Salesforce founder and pioneer of the 1-1-1 corporate philanthropy model, alongside major personal direct contributions to pediatric healthcare and microbiome science.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000030', 'Alice Walton', 'Alice', 'Walton', 'United States', 'Founder, Crystal Bridges Museum of American Art', 'Retail & Art Philanthropy', 'Walmart heir and founder of Crystal Bridges Museum of American Art in Bentonville, Arkansas, dedicated to accessible American art education.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000031', 'Jim Walton', 'James', 'Walton', 'United States', 'Chairman, Arvest Bank Group', 'Retail & Banking', 'Walmart heir and chairman of Arvest Bank. Regularly transfers substantial Walmart equity holdings to charitable family trusts via SEC Form 4 filings.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000032', 'Rob Walton', 'Samuel Robson', 'Walton', 'United States', 'Former Chairman, Walmart Inc. / Owner, Denver Broncos', 'Retail & Sports', 'Former chairman of Walmart Inc. and principal owner of the Denver Broncos. Transferred over $1.2B in Walmart equity to charitable trusts via regulatory filings.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000033', 'Ray Dalio', 'Raymond', 'Dalio', 'United States', 'Founder, Bridgewater Associates', 'Finance & Hedge Funds', 'Founder of Bridgewater Associates and Giving Pledge signatory. Supports oceanographic research (OceanX) and public education in Connecticut.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000034', 'George Lucas & Mellody Hobson', 'George', 'Lucas', 'United States', 'Filmmaker & Philanthropist', 'Entertainment & Film', 'Creator of Star Wars and founder of Lucasfilm. Pledged majority of wealth from Lucasfilm Disney sale to education philanthropy (Edutopia) and funded USC Cinematic Arts.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000035', 'Ken Griffin', 'Kenneth', 'Griffin', 'United States', 'Founder & CEO, Citadel', 'Finance & Hedge Funds', 'Founder and CEO of Citadel. Has directed landmark personal contributions to Harvard University, University of Chicago, and medical institutions.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000036', 'David Geffen', 'David', 'Geffen', 'United States', 'Founder, Geffen Records, Asylum Records & DreamWorks SKG', 'Entertainment & Music', 'Music and film pioneer (Asylum, Geffen Records, DreamWorks). Established major endowments for medical education at UCLA and performing arts institutions.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000037', 'Eli Broad (Historic)', 'Eli', 'Broad', 'United States', 'Founder, SunAmerica & KB Home / Philanthropist', 'Real Estate & Financial Services', 'Only person to build two Fortune 500 companies in different industries (KB Home, SunAmerica). With wife Edythe, gave away over $4 billion to genomics (Broad Institute) and civic arts.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000038', 'Melinda French Gates', 'Melinda', 'French Gates', 'United States', 'Founder, Pivotal Ventures / Philanthropist', 'Venture Capital & Philanthropy', 'Co-founder of the Bill & Melinda Gates Foundation and founder of Pivotal Ventures. Focuses independent philanthropic capital on global women''s rights and family economic security.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000039', 'Paul Allen (Historic)', 'Paul', 'Allen', 'United States', 'Co-Founder, Microsoft / Founder, Vulcan Inc.', 'Technology & Investments', 'Microsoft co-founder and founder of the Allen Institute. Committed over $2 billion to neuroscience, cell science, and wildlife conservation.', TRUE, FALSE),
('b0000000-0000-0000-0000-000000000040', 'John Doerr & Ann Doerr', 'John', 'Doerr', 'United States', 'Chairman, Kleiner Perkins', 'Venture Capital & Tech', 'Venture capitalist and Kleiner Perkins chairman. Pioneered Silicon Valley clean-tech venture investing and made a landmark $1.1B gift to establish Stanford''s sustainability school.', TRUE, FALSE)
